"""Clean-room Engine + create_engine stubs."""


class _TransactionContext:
    def __enter__(self):
        return self

    def __exit__(self, *args):
        pass

    def execute(self, *args, **kwargs):
        pass


class Engine:
    def connect(self, *args, **kwargs) -> _TransactionContext:
        return _TransactionContext()

    def begin(self, *args, **kwargs) -> _TransactionContext:
        return _TransactionContext()


def create_engine(*args, **kwargs) -> Engine:
    return Engine()
